const cfg = $input.first().json;
const quote = (value) => `"${String(value).replaceAll('"', '\\"')}"`;
const parts = [
  quote(cfg.pythonBin),
  quote(cfg.prepareScriptPath),
  '--start', String(cfg.startRow ?? 1),
  '--end', String(cfg.endRow ?? cfg.startRow ?? 1),
  '--outgoing-start', String(cfg.outgoingStart ?? 101),
];
return [{ json: { ...cfg, commandLine: parts.join(' ') } }];

const raw = $json.stdout || '';
const parsed = JSON.parse(raw);
if (!parsed.ok) {
  throw new Error(parsed.error || 'Prepare step failed');
}
return (parsed.items || []).map((item) => ({
  json: {
    ...item,
    workflowMeta: {
      xlsxPath: parsed.xlsx_path,
      selectedRange: parsed.selected_range,
    },
  },
}));

const cfg = $('Workflow Config').first().json;
const payload = ($json.reviews || []).map((review) => ({
  field: review.field,
  source_value: review.source_value,
  generated_value: review.generated_value,
  target_case: review.target_case,
  context_sentence: review.context_sentence,
  slot_instruction: review.slot_instruction,
  slot_label: review.slot_label,
}));
const prompt = [
  'Ты агент проверки русских формулировок в официальных документах.',
  'Твоя задача не угадывать падеж по имени поля, а определить, какой именно текст должен стоять в позиции [SLOT] внутри конкретной фразы шаблона.',
  'Смотри на всю фразу целиком и возвращай только подстановку для [SLOT].',
  'Не ориентируйся на старые примеры из шаблона как на эталон.',
  'Если внутри конструкции есть устойчивое официальное наименование, не склоняй его автоматически целиком без явной необходимости.',
  'Если generated_value уже корректно для позиции [SLOT], обязательно верни status="ok".',
  'Используй status="fix" только если corrected_value реально отличается от generated_value.',
  'Если случай спорный, верни status="needs_review".',
  'Для каждого поля обязательно верни confidence от 0.0 до 1.0.',
  'Верни только JSON-массив объектов вида {"field":"...", "status":"ok|fix|needs_review", "corrected_value":"...", "confidence":0.0, "comment":"..."}.',
  '',
  'Данные для проверки:',
  JSON.stringify(payload, null, 2),
].join('\n');
return [{
  json: {
    ...$json,
    openaiRequestBody: {
      model: cfg.caseAgentModel || 'gpt-4o-mini',
      response_format: { type: 'json_object' },
      messages: [
        {
          role: 'user',
          content: prompt,
        },
      ],
    },
  },
}];

const cfg = $('Workflow Config').first().json;
const reviews = $json.reviews || [];
let parsedItems = [];
let error = null;
try {
  const raw = $json.choices?.[0]?.message?.content || '{}';
  let parsed = JSON.parse(raw);
  if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
    parsed = parsed.items || parsed.result || parsed.results || parsed;
  }
  parsedItems = Array.isArray(parsed) ? parsed : [];
} catch (e) {
  error = e.message;
}
const reviewMap = new Map(reviews.map((review) => [review.field, review]));
const normalized = [];
const seen = new Set();
for (const item of parsedItems) {
  const field = item?.field;
  if (!field || !reviewMap.has(field)) continue;
  const review = reviewMap.get(field);
  const generated = String(review.generated_value || '').trim();
  const corrected = String(item.corrected_value ?? generated).trim() || generated;
  let status = String(item.status || 'needs_review').toLowerCase();
  let confidence = Number(item.confidence ?? 0);
  if (!Number.isFinite(confidence)) confidence = 0;
  let comment = String(item.comment || '').trim();
  if (!['ok', 'fix', 'needs_review'].includes(status)) status = 'needs_review';
  if (corrected !== generated && status === 'ok') status = 'fix';
  if (corrected === generated && status === 'fix') {
    status = 'ok';
    if (!comment) comment = 'Сгенерированная форма уже корректна.';
  }
  if ((status === 'ok' || status === 'fix') && confidence <= 0) confidence = 0.8;
  normalized.push({
    field,
    source_value: review.source_value,
    generated_value: generated,
    status,
    corrected_value: corrected,
    confidence,
    comment,
  });
  seen.add(field);
}
for (const review of reviews) {
  if (seen.has(review.field)) continue;
  normalized.push({
    field: review.field,
    source_value: review.source_value,
    generated_value: review.generated_value,
    status: 'needs_review',
    corrected_value: review.generated_value,
    confidence: 0,
    comment: error || 'Поле отсутствует в ответе AI-агента.',
  });
}
const summary = {
  reviewed_fields_count: reviews.length,
  ok_count: normalized.filter((item) => item.status === 'ok').length,
  fix_count: normalized.filter((item) => item.status === 'fix').length,
  needs_review_count: normalized.filter((item) => item.status === 'needs_review').length,
};
return [{
  json: {
    ...$json,
    agent_result: {
      enabled: true,
      mode: cfg.caseAgentMode || 'auto_fix',
      error,
      items: normalized,
      summary,
    },
  },
}];

const cfg = $('Workflow Config').first().json;
const quote = (value) => `"${String(value).replaceAll('"', '\\"')}"`;
const payload = {
  row: $json.row,
  context: $json.context,
  agent_result: $json.agent_result,
};
const payloadBase64 = Buffer.from(JSON.stringify(payload), 'utf8').toString('base64');
const parts = [
  quote(cfg.pythonBin),
  quote(cfg.renderScriptPath),
  '--payload-base64',
  quote(payloadBase64),
];
return [{ json: { ...$json, renderCommand: parts.join(' ') } }];

const items = $input.all().map((entry) => entry.json);
return [{
  json: {
    status: items.every((item) => item.ok !== false) ? 'success' : 'partial_or_failed',
    totalItems: items.length,
    folders: items.map((item) => ({
      mun_name: item.mun_name,
      output_folder: item.output_folder,
      review_path: item.review_path,
      case_agent_status: item.case_agent_status,
      case_agent_summary: item.case_agent_summary,
    })),
  },
}];
